 p['peer_review']=dict(proof='peer-reconciliation.json',proof_sha256=sha((D/'peer-reconciliation.json').read_bytes()),peer_capture='history/baseline-final-peer/capture.json',peer_capture_index_sha256=r['peer_capture_index_sha256'],peer_manifest_at_capture_sha256=r['peer_capture_manifest_sha256'],own_prechange_capture='history/turnout-pre-peer/capture.json',own_prechange_capture_sha256=r['own_pre_peer_capture_index_sha256'],comparison_checks=r['comparison_checks'],scope=r['coverage'],source_position_mapping=r['source_position_mapping'],exclusions=r['exclusions'],future_final_byte_equality=False,calculator_validation_admitted=False,coordinator_acceptance=False)
